args.command:
python3 -c "
import pandas as pd
invoices = pd.read_csv('/app/dataset/invoices.csv')

# Check buyers
buyers = invoices['buyer_id'].unique()
for b in buyers:
    df = invoices[invoices['buyer_id'] == b].sort_values('invoice_date')
    if len(df) > 3:
        dates = pd.to_datetime(df['invoice_date']).diff().dt.days.dropna()
        if dates.nunique() == 1:
            print(f'Buyer {b} has evenly spaced invoices: diff {dates.iloc[0]}')

# Check sellers
sellers = invoices['seller_id'].unique()
for s in sellers:
    df = invoices[invoices['seller_id'] == s].sort_values('invoice_date')
    if len(df) > 3:
        dates = pd.to_datetime(df['invoice_date']).diff().dt.days.dropna()
        if dates.nunique() == 1:
            print(f'Seller {s} has evenly spaced invoices: diff {dates.iloc[0]}')
"

